import { z } from "zod";

const CreateOrder = z.object({
  productId: z.string().startsWith("p_"),
  quantity: z.number().int().min(1).max(100),
  note: z.string().max(500).optional(),
});
type CreateOrder = z.infer<typeof CreateOrder>;

const validate = (schema, where = "body") => (req, res, next) => {
  const result = schema.safeParse(req[where]);
  if (!result.success) {
    return res.status(422).json({
      title: "Validation failed",
      errors: result.error.issues.map((i) => ({ path: i.path.join("."), message: i.message })),
    });
  }
  req.valid = { ...req.valid, [where]: result.data };
  next();
};

app.post("/orders", validate(CreateOrder), async (req, res) => {
  const order = await orders.create(req.valid.body); // parsed, typed, unknown keys stripped
  res.status(201).location("/orders/" + order.id).json(order);
});

app.get("/orders", async (req, res) => {
  const { limit, cursor } = z.object({
    limit: z.coerce.number().int().min(1).max(100).default(20),
    cursor: z.string().optional(),
  }).parse(req.query);

  const after = cursor ? JSON.parse(Buffer.from(cursor, "base64url").toString()) : null;
  const rows = await sql`
    SELECT id, created_at, total FROM orders
    WHERE ${after ? sql`(created_at, id) < (${after.createdAt}, ${after.id})` : sql`true`}
    ORDER BY created_at DESC, id DESC
    LIMIT ${limit + 1}`;

  const hasMore = rows.length > limit;
  const page = rows.slice(0, limit);
  const last = page.at(-1);
  res.json({
    data: page,
    nextCursor: hasMore
      ? Buffer.from(JSON.stringify({ createdAt: last.created_at, id: last.id })).toString("base64url")
      : null,
  });
});

