import { WebSocketServer } from "ws";

const wss = new WebSocketServer({ server: httpServer, maxPayload: 64 * 1024 });

wss.on("connection", (socket, req) => {
  const user = authenticateFromCookie(req.headers.cookie);
  if (!user) return socket.close(1008, "unauthorized");

  socket.isAlive = true;
  socket.on("pong", () => (socket.isAlive = true));
  socket.on("message", (raw) => {
    const msg = JSON.parse(raw.toString());           // validate in real code
    redisPub.publish("room:" + msg.roomId, JSON.stringify({ from: user.id, text: msg.text }));
  });
});

setInterval(() => {
  for (const s of wss.clients) {
    if (!s.isAlive) { s.terminate(); continue; }
    s.isAlive = false;
    s.ping();
  }
}, 30_000);

import crypto from "node:crypto";

app.post("/webhooks/payments", express.raw({ type: "application/json" }), async (req, res) => {
  const ts = req.get("webhook-timestamp");
  const sig = req.get("x-signature") ?? "";
  const expected = crypto.createHmac("sha256", process.env.WEBHOOK_SECRET)
    .update(ts + "." + req.body)            // req.body is the raw Buffer here
    .digest("hex");

  const fresh = Math.abs(Date.now() / 1000 - Number(ts)) < 300;
  const valid = sig.length === expected.length &&
    crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
  if (!fresh || !valid) return res.sendStatus(400);

  const event = JSON.parse(req.body);
  const inserted = await db.webhookEvents.insertIfAbsent(event.id); // unique constraint
  if (inserted) await queue.add("payment-event", event);
  res.sendStatus(200); // acknowledge fast, process in the background
});

