await ch.assertExchange("orders", "topic", { durable: true });
await ch.assertQueue("email.order-placed", { durable: true, arguments: { "x-queue-type": "quorum" } });
await ch.bindQueue("email.order-placed", "orders", "order.placed");

ch.publish("orders", "order.placed", Buffer.from(JSON.stringify({ orderId: "o_1" })), {
  persistent: true, messageId: "evt_123",
});

await ch.prefetch(10);
await ch.consume("email.order-placed", async (msg) => {
  try {
    await handle(JSON.parse(msg.content.toString()));
    ch.ack(msg);
  } catch {
    ch.nack(msg, false, false); // to the dead-letter exchange, if configured
  }
});
